// Pega o CSV como texto vindo HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

// Linhas de dados
const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// ============================================================
// Node: Code in JavaScript1
// Mode: "Run Once for All Items"
// Entrada: item único vindo do Merge, com:
//   json.clientes      -> array [{ nome, email, saldo, perfil }]
//   json.investimentos -> array [{ perfil, produto, minimo, rentabilidade }]
// ============================================================

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// Pega o item mesclado (Merge combina os 2 inputs em 1 item só)
const merged = $input.first().json;

// Os dados do Webhook vêm dentro de "body" (headers, params, query, body)
const clientes = merged.clientes || (merged.body && merged.body.clientes) || [];
const investimentos = merged.investimentos || (merged.body && merged.body.investimentos) || [];

// Monta um lookup rápido: perfil -> produto recomendado
// (vem do CSV, não é mais fixo no código)
const tabelaRecomendacoes = {};
investimentos.forEach((inv) => {
  tabelaRecomendacoes[inv.perfil] = inv;
});

const resultados = clientes.map((c) => {
  // Converte "R$ 12.500,00" -> 12500 (número)
  const saldoNum = Number(
    String(c.saldo)
      .replace('R$', '')
      .replace(/\./g, '')
      .replace(',', '.')
      .trim()
  );

  const perfil = c.perfil || 'Conservador';
  const rec = tabelaRecomendacoes[perfil] || tabelaRecomendacoes['Conservador'];

  // Verifica se o saldo atende ao mínimo do produto recomendado
  const atendeMinimo = rec ? saldoNum >= Number(rec.minimo) : false;
  const escolhido = atendeMinimo ? perfil : 'Conservador';
  const recFinal = tabelaRecomendacoes[escolhido] || rec;
  const motivo = atendeMinimo ? 'saldo_ok' : 'saldo_insuficiente';

  const recomendacao = {
    perfil: escolhido,
    produto: recFinal ? recFinal.produto : null,
    minimo: recFinal ? recFinal.minimo : null,
    rentabilidade: recFinal ? recFinal.rentabilidade : null
  };

  const mensagens = [
    `Olá ${c.nome}! Pelo seu perfil (${escolhido}), uma boa opção é **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo},00). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `Oi ${c.nome}! Recomendação para perfil ${escolhido}: **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo},00). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `${c.nome}, indo direto ao ponto: para o perfil ${escolhido}, **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo},00). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${recomendacao.rentabilidade}.`
  ];

  return {
    nome: c.nome,
    email: c.email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0; 
    const s = String(valor)
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .replace(/[^\d.]/g, "")
      .trim();
    const n = Number(s);
    return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

