// ============================================================
// Node: Code in JavaScript3
// Mode: "Run Once for All Items"
//
// Entrada: saída do node "Message a model" (1 item por cliente).
// O texto gerado pela IA é um JSON (string) com subject/text_body/html_body.
// O caminho do texto varia conforme a versão do node do Gemini,
// por isso vários caminhos são tentados.
//
// Também busca os dados originais do cliente (nome, perfil,
// email_to, recomendacao, motivo) no node "Code in JavaScript2",
// casando pelo mesmo índice (mesma ordem dos itens).
// ============================================================

const items = $input.all();
const originais = $('Code in JavaScript2').all();

return items.map((item, index) => {
  const original = (originais[index] && originais[index].json) || {};
  const j = item.json || {};

  // Pega o texto bruto gerado pela IA (tenta os formatos conhecidos)
  const raw =
    j.content?.parts?.[0]?.text ||
    j.candidates?.[0]?.content?.parts?.[0]?.text ||
    j.output?.output?.[0]?.content?.[0]?.text ||
    j.content?.[0]?.text ||
    j.text ||
    '';

  // Remove blocos de markdown ```json ... ``` caso a IA os inclua
  const limpo = raw.replace(/```json/g, '').replace(/```/g, '').trim();

  let parsed = {};
  try {
    parsed = JSON.parse(limpo);
  } catch (e) {
    // Se não vier em JSON válido, usa o texto cru como corpo da mensagem
    parsed = { subject: '', text_body: raw, html_body: '' };
  }

  const to = original.email_to || original.email || original.to || '';
  const subject = parsed.subject || original.subject || '';
  const text_body = parsed.text_body || '';
  const html_body = parsed.html_body || '';

  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis para debug/aula
      meta: {
        nome: original.nome,
        perfil: original.perfil,
        produto: original.recomendacao?.produto,
        minimo: original.recomendacao?.minimo,
        rentabilidade: original.recomendacao?.rentabilidade,
        motivo: original.motivo
      }
    }
  };
});
